//! Generate `.horus/Cargo.toml` from `horus.toml` dependencies.
//!
//! This module is the bridge between the unified horus manifest and the Cargo
//! build system. It reads `[dependencies]` from `horus.toml`, filters for
//! Rust-relevant deps (crates.io, path, git, registry), and produces a
//! valid `Cargo.toml` inside `.horus/`.
//!
//! The generated file is always gitignored and treated as a build artifact.

use anyhow::{Context, Result};
use colored::Colorize;
use std::collections::BTreeMap;
use std::fmt::Write as FmtWrite;
use std::fs;
use std::path::{Path, PathBuf};

use crate::manifest::{DepSource, DependencyValue, HorusManifest};

/// The `.horus` build directory name.
const HORUS_DIR: &str = ".horus";

/// Generate `.horus/Cargo.toml` from a `HorusManifest`.
///
/// - Filters crates.io, path, git, and registry deps from `[dependencies]`
/// - Adds horus_core/horus_library as path deps (found via `find_horus_source_dir`)
/// - Creates `[[bin]]` entries from source files
/// - Returns the path to the generated `Cargo.toml`
///
/// # Arguments
///
/// * `manifest` - The parsed horus.toml manifest
/// * `project_dir` - The project root directory (where horus.toml lives)
/// * `source_files` - List of .rs source files to create [[bin]] entries for
/// * `include_dev` - Whether to include dev-dependencies (for `horus test`)
pub fn generate(
    manifest: &HorusManifest,
    project_dir: &Path,
    source_files: &[PathBuf],
    include_dev: bool,
) -> Result<(PathBuf, String)> {
    let horus_dir = project_dir.join(HORUS_DIR);
    fs::create_dir_all(&horus_dir).context("Failed to create .horus directory")?;

    let project_name = &manifest.package.name;
    let version = &manifest.package.version;

    let mut cargo = String::with_capacity(2048);

    // ── Header ───────────────────────────────────────────────────────────
    writeln!(
        cargo,
        "# Generated by horus from horus.toml — do not edit manually.\n\
         # Edits are lost on the next build; add a [rust] section to horus.toml instead."
    )
    .unwrap();
    writeln!(cargo, "[package]").unwrap();
    writeln!(cargo, "name = \"{}\"", sanitize_cargo_name(project_name)).unwrap();
    writeln!(cargo, "version = \"{}\"", version).unwrap();
    writeln!(cargo, "edition = \"{}\"", rust_edition(manifest)).unwrap();
    writeln!(cargo).unwrap();

    // ── Workspace isolation ──────────────────────────────────────────────
    // Prevents inheriting a parent workspace
    writeln!(cargo, "[workspace]").unwrap();
    writeln!(cargo).unwrap();

    // ── Binary targets ───────────────────────────────────────────────────
    if source_files.is_empty() {
        // Default: look for main.rs in project root
        let main_rs = project_dir.join("main.rs");
        let src_main = project_dir.join("src/main.rs");
        if main_rs.exists() {
            write_bin_entry(
                &mut cargo,
                project_name,
                &relative_to_horus(&main_rs, &horus_dir),
            );
        } else if src_main.exists() {
            write_bin_entry(
                &mut cargo,
                project_name,
                &relative_to_horus(&src_main, &horus_dir),
            );
        }
    } else if source_files.len() == 1 {
        let rel = relative_to_horus(&source_files[0], &horus_dir);
        write_bin_entry(&mut cargo, project_name, &rel);
    } else {
        for file in source_files {
            let stem = file
                .file_stem()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_else(|| "main".to_string());
            let rel = relative_to_horus(file, &horus_dir);
            write_bin_entry(&mut cargo, &stem, &rel);
        }
    }

    // ── Auto-install missing registry deps ────────────────────────────────
    auto_install_registry_deps(&manifest.dependencies, project_dir, &horus_dir)?;
    if include_dev && !manifest.dev_dependencies.is_empty() {
        auto_install_registry_deps(&manifest.dev_dependencies, project_dir, &horus_dir)?;
    }

    // ── Dependencies ─────────────────────────────────────────────────────
    writeln!(cargo, "[dependencies]").unwrap();

    // Add horus core path deps.
    //
    // This is not optional: without it `[dependencies]` is emitted empty and the
    // user's project fails with a wall of `cannot find type Topic/Scheduler`
    // rustc errors instead of the actionable message find_horus_source_dir()
    // already produces. Propagate that message rather than swallowing it.
    let horus_source = crate::commands::run::find_horus_source_dir()
        .context("Cannot generate .horus/Cargo.toml without the HORUS source tree")?;
    write_horus_path_deps(&mut cargo, &horus_source, manifest);
    write_implicit_deps(&mut cargo, manifest);
    write_generated_msgs_dep(&mut cargo, project_dir, manifest);

    // Add user deps from horus.toml
    write_deps_section(&mut cargo, &manifest.dependencies, project_dir, &horus_dir)?;

    // Add driver dependencies from [drivers] config tables
    write_driver_deps(&mut cargo, &manifest.drivers);

    // ── Dev dependencies ─────────────────────────────────────────────────
    if include_dev && !manifest.dev_dependencies.is_empty() {
        writeln!(cargo).unwrap();
        writeln!(cargo, "[dev-dependencies]").unwrap();
        write_deps_section(
            &mut cargo,
            &manifest.dev_dependencies,
            project_dir,
            &horus_dir,
        )?;
    }

    // ── [rust] passthrough ───────────────────────────────────────────────
    // Before the patches, for the same reason they come last.
    if let Some(rust) = &manifest.rust {
        write_rust_passthrough(&mut cargo, rust, PACKAGE_RUST_SECTIONS);
    }

    // ── Patch tables ─────────────────────────────────────────────────────
    // Last: [patch.*] is a top-level table and would swallow later entries.
    write_patch_sections(&mut cargo, &horus_source, manifest.rust.as_ref());

    // ── Write file ───────────────────────────────────────────────────────
    let cargo_toml_path = horus_dir.join("Cargo.toml");
    let mut fingerprints = crate::fingerprint::Fingerprints::load(project_dir).unwrap_or_default();
    write_generated(
        project_dir,
        "Cargo.toml",
        &cargo_toml_path,
        &cargo,
        &mut fingerprints,
        &sections_horus_toml_keeps(manifest),
    )?;
    let _ = fingerprints.save(project_dir);

    // Not part of the manifest — see write_cargo_config.
    write_cargo_config(project_dir, &horus_dir, manifest.rust.as_ref())?;
    ignore_generated_dir(&horus_dir, BUILD_DIR_IS_GENERATED);

    Ok((cargo_toml_path, cargo))
}

/// Say which `[rust]` settings a workspace build cannot place, and where they go.
///
/// WHY THIS IS NO LONGER A BLANKET WARNING. The first version of this said
/// "workspace builds do not forward it yet — only `edition` takes effect", and
/// that was wrong in both directions. `rustflags` already reached a workspace:
/// `horus test` spawns cargo from inside `.horus/`, so it read the generated
/// cargo config and died on a bogus flag while `horus build` was printing that
/// the section had no effect. And the settings that genuinely were dropped were
/// never named, so the warning could not be acted on. Worse, the lost-edit
/// warning on a member manifest told users to move a `[patch]` into `[rust]`,
/// and this one then told them `[rust]` does nothing here — two contradictory
/// instructions about the same setting, with the manifest still eating it.
///
/// `generate_workspace` now forwards the section (root `profile` and `patch` to
/// the root manifest, root `lints` and every member's own tables into the
/// member manifests, `rustflags` to the cargo config). What is left is the set
/// cargo will not accept in the position a workspace would have to put it in,
/// and each of those gets named with the manifest it is in and the move that
/// makes it work.
fn warn_about_rust_settings_a_workspace_cannot_place(
    root_manifest: &HorusManifest,
    members: &[(PathBuf, HorusManifest)],
) {
    let unplaceable = rust_settings_a_workspace_cannot_place(root_manifest, members);
    if unplaceable.is_empty() {
        return;
    }
    let mut msg = "horus.toml settings this workspace build cannot apply:".to_string();
    for item in &unplaceable {
        msg.push_str("\n    - ");
        msg.push_str(item);
    }
    crate::cli_output::warn(&msg);
}

/// The `[rust]` settings a workspace build has nowhere to put, each named with
/// the manifest it is in and the move that makes it work.
///
/// Split out from the warning so the decision is testable without capturing
/// stderr — the list is the part that has to be right.
fn rust_settings_a_workspace_cannot_place(
    root_manifest: &HorusManifest,
    members: &[(PathBuf, HorusManifest)],
) -> Vec<String> {
    let mut unplaceable: Vec<String> = Vec::new();

    // A virtual workspace root has no `[package]`, and cargo rejects a virtual
    // manifest that carries package-level tables outright ("this virtual
    // manifest specifies a `features` section, which is not allowed"). Writing
    // them would break the build rather than ignore the setting.
    if let Some(rust) = &root_manifest.rust {
        for (name, table) in [
            ("features", &rust.features),
            ("build-dependencies", &rust.build_dependencies),
            ("target", &rust.target),
        ] {
            if table.as_ref().is_some_and(|t| !t.is_empty()) {
                unplaceable.push(format!(
                    "[rust.{name}] in the workspace root — a virtual workspace \
                     has no package to attach it to; put it in the horus.toml of \
                     the member that needs it"
                ));
            }
        }
    }

    for (rel_path, member) in members {
        let Some(rust) = &member.rust else {
            continue;
        };
        let where_ = rel_path.join(crate::manifest::HORUS_TOML);
        let where_ = where_.display();
        if rust.profile.as_ref().is_some_and(|t| !t.is_empty()) {
            unplaceable.push(format!(
                "[rust.profile] in {where_} — cargo honours profiles only at the \
                 workspace root; move it to the root horus.toml"
            ));
        }
        if rust.patch.as_ref().is_some_and(|t| !t.is_empty()) {
            unplaceable.push(format!(
                "[rust.patch] in {where_} — [patch] applies to a whole workspace; \
                 move it to the root horus.toml"
            ));
        }
        if !rust.rustflags.is_empty() {
            unplaceable.push(format!(
                "[rust].rustflags in {where_} — rustflags are set per build \
                 directory, and a workspace has one; move them to the root \
                 horus.toml"
            ));
        }
    }

    unplaceable
}

/// The `.gitignore` reason for `.horus/`.
const BUILD_DIR_IS_GENERATED: &str =
    "`.horus/` is a build directory — nothing in it belongs in version control.";

/// The `.gitignore` reason for a `.cargo/` directory HORUS created.
const CARGO_CONFIG_DIR_IS_GENERATED: &str =
    "this .cargo/ directory holds nothing but the config HORUS generates from\n\
     # [rust].rustflags in horus.toml.";

/// Keep a directory HORUS generates out of `git status`, the way cargo keeps
/// `target/` out.
///
/// The generated project `.gitignore` names the contents of `.horus/` one path
/// at a time — `.horus/target/`, `.horus/Cargo.toml`, `.horus/packages/` and so
/// on — so every new generated file starts life untracked and visible.
/// `fingerprints.json` was already in that state, and the cargo config
/// `write_cargo_config` emits would be the next. Enumerating them in a template
/// that only runs at `horus new` also leaves every project created before the
/// addition behind.
///
/// A `.gitignore` inside the generated directory itself is how cargo solves
/// this for `target/`, and it covers the whole directory for old and new
/// projects at once — including the `.gitignore`, which `*` matches too, so the
/// directory disappears from `git status` entirely instead of trading one
/// untracked path for another.
///
/// Written only when absent, and — for a directory outside `.horus/` — only
/// when HORUS created it: it is the user's repository, and neither a file they
/// have changed nor a directory that was already theirs is ours to hide.
/// Failure is ignored; this is tidiness, and a build must not stop for it.
fn ignore_generated_dir(dir: &Path, what: &str) {
    let path = dir.join(".gitignore");
    if path.exists() {
        return;
    }
    let _ = fs::write(&path, format!("# Generated by horus. {what}\n*\n"));
}

/// How many discarded settings to name before summarising the rest.
const LOST_EDIT_LIMIT: usize = 8;

/// Write a generated file, saying what it is about to throw away.
///
/// WHY THIS EXISTS. Regeneration was unconditional: `.horus/Cargo.toml` was
/// rewritten on every build and anything a user had put in it by hand vanished
/// without a word. The header said "do not edit manually", but nothing said the
/// file was *regenerated*, and until `[rust]` existed there was no supported
/// alternative — so hand-editing was the workaround for the very problem it
/// then caused. Losing an edit is survivable; losing it in silence, in the file
/// the tool told you not to touch, is what made it expensive to diagnose.
///
/// WHY NOT A PLAIN DIFF. "The file differs from what we would generate" is true
/// on any legitimate `horus.toml` change too, and a warning that fires on every
/// second build teaches people to scroll past it. The interesting set is
/// narrower: settings that are in the file, were *not* put there by HORUS, and
/// are *not* in the content about to replace them. The fingerprint recorded
/// below answers the middle part — every write records exactly what it wrote,
/// so a mismatch means something other than HORUS touched the file — and a
/// key-by-key comparison answers the last. That keeps `horus cargo add` quiet:
/// cargo edits the same file, but the dependency is synced back into
/// `horus.toml` and reappears in the regenerated content, so nothing is lost.
///
/// A project generated by an older HORUS has no fingerprint yet, so its first
/// regeneration cannot tell a hand edit from an ordinary one and stays silent.
/// It records on the way out, and every regeneration after that can.
///
/// `kept` names the tables `horus.toml` still holds even when this particular
/// regeneration does not emit them — see `sections_horus_toml_keeps`, which is
/// what stops `horus cargo add --dev` from reporting a loss that did not
/// happen.
fn write_generated(
    project_dir: &Path,
    key: &str,
    path: &Path,
    content: &str,
    fingerprints: &mut crate::fingerprint::Fingerprints,
    kept: &[KeptSection],
) -> Result<()> {
    if fingerprints.is_modified(key, project_dir) {
        let existing = fs::read_to_string(path).unwrap_or_default();
        let lost = dropped_settings(&existing, content, kept);
        if !lost.is_empty() {
            // Named relative to the project: an absolute path here is a
            // tempdir-long line in front of the part that matters. The key
            // doubles as the position: `Cargo.toml` is the root or a standalone
            // package, `<member>/Cargo.toml` is a workspace member, and the two
            // do not take the same advice.
            report_lost_edits(
                path.strip_prefix(project_dir).unwrap_or(path),
                &lost,
                key.contains('/'),
            );
        }
    }

    fs::write(path, content).with_context(|| format!("Failed to write {}", path.display()))?;
    fingerprints.record(key, content);
    Ok(())
}

/// A table of the generated manifest that `horus.toml` also holds, with the
/// keys it holds.
type KeptSection = (&'static str, Vec<String>);

/// Tables `horus.toml` carries whether or not this regeneration emits them.
///
/// WHY THIS EXISTS. `generate` takes `include_dev`, and it is false everywhere
/// but `horus test`: an ordinary build, and every `horus cargo <cmd>`
/// sync-back, rewrites the manifest with no `[dev-dependencies]` table at all.
/// The table therefore disappears from the file on a flow that lost nothing,
/// and a plain key diff called that a destroyed hand edit —
///
/// ```text
/// $ horus cargo add --dev rand
///   ⟳ Synced 2 new dep(s) to horus.toml
/// ! .horus/Cargo.toml is generated from horus.toml and has just been
///   rewritten, discarding settings that were added to it directly:
///     dev-dependencies
/// ```
///
/// — every single time, on the flow that is *supposed* to be used. A warning
/// that cries wolf on a normal command is worse than no warning: it trains
/// people to scroll past the one that is real, and here it also mixed into the
/// same list as real losses.
///
/// The honest question is not "is the table still in the file" but "does
/// horus.toml still have this crate". Anything horus.toml knows about comes
/// back the next time a path asks for dev-dependencies; a crate that only ever
/// existed in the generated file does not, and is still reported — by name, and
/// pointed at `[dev-dependencies]` rather than at `[rust]`.
fn sections_horus_toml_keeps(manifest: &HorusManifest) -> Vec<KeptSection> {
    vec![(
        "dev-dependencies",
        manifest.dev_dependencies.keys().cloned().collect(),
    )]
}

/// Tell the user which of their edits just went away, and where they belong.
///
/// The advice is per key, because one line for all of them was wrong for the
/// keys people actually lose — see `horus_toml_home`.
fn report_lost_edits(path: &Path, lost: &[String], in_workspace_member: bool) {
    let named: Vec<&String> = lost.iter().take(LOST_EDIT_LIMIT).collect();
    let width = named.iter().map(|n| n.chars().count()).max().unwrap_or(0);

    let mut msg = format!(
        "{} is generated from horus.toml and has just been rewritten, \
         discarding settings that were added to it directly:",
        path.display()
    );
    let mut any_homeless = false;
    for name in &named {
        match horus_toml_home(name) {
            Some(home) => {
                let which = which_horus_toml(name, in_workspace_member);
                let _ = write!(
                    msg,
                    "\n    {name:<width$}  → put it under {home} in {which}"
                );
            }
            None => {
                any_homeless = true;
                let _ = write!(msg, "\n    {name:<width$}  → no horus.toml equivalent");
            }
        }
    }
    if lost.len() > LOST_EDIT_LIMIT {
        let _ = write!(msg, "\n    ... and {} more", lost.len() - LOST_EDIT_LIMIT);
    }
    msg.push_str(
        "\n  Those sections of horus.toml are written into this file on every \
         regeneration, so a setting kept there survives.",
    );
    if any_homeless {
        let _ = write!(
            msg,
            "\n  [rust] forwards {}; a Cargo.toml section outside that list has \
             nowhere in horus.toml to live yet.",
            rust_forwarded_sections().join(", ")
        );
    }

    // The tests watch this, not `dropped_settings`: the diff being right proves
    // nothing if nobody is told. See `reported_lost_edits`.
    #[cfg(test)]
    REPORTED_LOST_EDITS.with(|reported| reported.borrow_mut().push(msg.clone()));

    crate::cli_output::warn(&msg);
}

// Every warning `report_lost_edits` has emitted on this thread.
//
// The user-visible warning is the whole of this fix, and a test that calls
// `dropped_settings` itself only proves the diff works — deleting the report
// call left every such test green. This is the seam that makes the emission
// itself testable, and it exists only in test builds.
#[cfg(test)]
thread_local! {
    static REPORTED_LOST_EDITS: std::cell::RefCell<Vec<String>> =
        std::cell::RefCell::new(Vec::new());
}

/// Take (and clear) the warnings emitted on this thread.
#[cfg(test)]
fn reported_lost_edits() -> Vec<String> {
    REPORTED_LOST_EDITS.with(|reported| std::mem::take(&mut *reported.borrow_mut()))
}

/// The `[rust]` keys that are Cargo.toml sections spliced into the generated
/// manifest, in the order they are listed to the user.
///
/// Read off `manifest_lint::KNOWN_RUST` rather than written out a second time,
/// so a section that stops being accepted by `horus check` stops being
/// suggested here. `edition` and `rustflags` are excluded: neither is a
/// Cargo.toml section, so neither can ever turn up in this diff.
fn rust_forwarded_sections() -> Vec<&'static str> {
    crate::manifest_lint::KNOWN_RUST
        .iter()
        .copied()
        .filter(|key| !matches!(*key, "edition" | "rustflags"))
        .collect()
}

/// Where a setting the rewrite dropped can be put so that it survives.
///
/// WHY PER KEY. One line of advice for every key was wrong for the keys people
/// actually lose. `dev-dependencies` is a top-level table of horus.toml and
/// `[rust.dev-dependencies]` is not a thing, so following the old message
/// literally produced an error from HORUS's own validator:
///
/// ```text
/// $ horus check
/// x unknown key `rust.dev-dependencies` — the section is spelled
///   `[dev-dependencies]`. It has no effect.
/// ```
///
/// Advice that fails the tool's own check is worse than no advice. `[rust]` is
/// the right answer only for the Cargo sections `[rust]` forwards, and this
/// says so key by key — including the sub-path, so `patch.crates-io` names
/// `[rust.patch.crates-io]`, which is the header the user can paste.
/// Which manifest that section has to go in.
///
/// WHY THIS IS NOT ALWAYS "horus.toml". On a workspace, `[patch]` and
/// `[profile]` are honoured only in the root — cargo ignores a member's — so
/// `generate_workspace` forwards them from the root manifest and from nowhere
/// else. A member's `.horus/<name>/Cargo.toml` losing a hand-written `[patch]`
/// and being told to put it "under [rust.patch] in horus.toml" sent the user to
/// the member's horus.toml, where it does nothing:
///
/// ```text
/// ! .horus/ws/Cargo.toml ... discarding settings ...: patch
///   Put them under [rust] in horus.toml ...
/// $ (adds [rust.patch.crates-io] to crates/ws/horus.toml, rebuilds)
/// ! horus.toml settings this workspace build cannot apply:
///     - [rust.patch] in crates/ws/horus.toml — ...
/// ```
///
/// Two messages contradicting each other about one setting is worse than one
/// message being incomplete, so the first one names the manifest that works.
fn which_horus_toml(dotted: &str, in_workspace_member: bool) -> &'static str {
    let section = dotted.split('.').next().unwrap_or(dotted);
    if in_workspace_member && matches!(section, "patch" | "profile") {
        "the workspace root's horus.toml"
    } else {
        "horus.toml"
    }
}

fn horus_toml_home(dotted: &str) -> Option<String> {
    let section = dotted.split('.').next()?;
    match section {
        // Written into the generated manifest from horus.toml's own dependency
        // tables — `horus cargo add` is the supported way to edit them.
        "dependencies" | "dev-dependencies" => Some(format!("[{section}]")),
        _ if rust_forwarded_sections().contains(&section) => Some(format!("[rust.{dotted}]")),
        _ => None,
    }
}

/// Settings present in `old` that `new` does not have, as dotted paths.
///
/// Compared as parsed TOML rather than as text, because the two are written by
/// different code paths and differ constantly in ways that mean nothing: cargo
/// writes `serde = { version = "1", features = [...] }` where HORUS writes
/// `serde = "1"`, and a line-level diff would call every one of those a lost
/// edit. Presence of the key is what matters — a value HORUS rewrote is still
/// there, a key that no longer exists is not.
///
/// Unparsable input yields nothing. If the file on disk is not valid TOML there
/// is no way to say which of its settings a rewrite would drop, and guessing
/// from the text would produce exactly the false alarms this avoids.
fn dropped_settings(old: &str, new: &str, kept: &[KeptSection]) -> Vec<String> {
    let (Ok(old), Ok(mut new)) = (
        toml::from_str::<toml::Value>(old),
        toml::from_str::<toml::Value>(new),
    ) else {
        return Vec::new();
    };
    graft_kept_sections(&mut new, kept);
    let mut lost = Vec::new();
    collect_missing(&old, &new, &mut Vec::new(), &mut lost);
    lost
}

/// Put the tables horus.toml still holds back into the replacement, so the
/// diff asks "is this setting gone" rather than "is it in this one file".
///
/// Only presence matters (see `collect_missing`), so the grafted entries carry
/// a placeholder value: a `[dev-dependencies]` this regeneration did not emit
/// is treated as still holding every crate horus.toml lists, and a crate
/// horus.toml has never heard of is still reported.
fn graft_kept_sections(new: &mut toml::Value, kept: &[KeptSection]) {
    let Some(table) = new.as_table_mut() else {
        return;
    };
    for (section, keys) in kept {
        let entry = table
            .entry(section.to_string())
            .or_insert_with(|| toml::Value::Table(toml::value::Table::new()));
        let Some(entry) = entry.as_table_mut() else {
            continue;
        };
        for key in keys {
            entry
                .entry(key.clone())
                .or_insert_with(|| toml::Value::Boolean(true));
        }
    }
}

/// Walk `old`, recording the path of every key `new` does not also have.
///
/// Recursion stops at the first missing key: reporting `patch.crates-io` says
/// what was lost, and listing each entry underneath it would bury that in
/// noise. Arrays are leaves — `[[bin]]` is HORUS's to write, and a
/// per-element comparison would report a reordering as a deletion.
fn collect_missing(
    old: &toml::Value,
    new: &toml::Value,
    path: &mut Vec<String>,
    lost: &mut Vec<String>,
) {
    let Some(old_table) = old.as_table() else {
        return;
    };
    for (key, value) in old_table {
        path.push(key.clone());
        match new.as_table().and_then(|t| t.get(key)) {
            None => lost.push(render_path(path)),
            // Descend only while both sides are still tables. A key whose
            // *shape* changed is present either way, and treating
            // `serde = { version = "1" }` becoming `serde = "1"` as three lost
            // settings would fire on a rewrite that lost nothing.
            Some(replacement) => {
                if value.is_table() && replacement.is_table() {
                    collect_missing(value, replacement, path, lost);
                }
            }
        }
        path.pop();
    }
}

/// A key path as it would be written in a TOML header, quoting the segments
/// that need it — `patch."https://github.com/x.git".somecrate`.
fn render_path(path: &[String]) -> String {
    path.iter()
        .map(|segment| {
            let bare = !segment.is_empty()
                && segment
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_');
            if bare {
                segment.clone()
            } else {
                format!("{segment:?}")
            }
        })
        .collect::<Vec<_>>()
        .join(".")
}

/// First line of a cargo config HORUS generated, and the test for whether a
/// cargo config on disk is ours to rewrite.
const GENERATED_CARGO_CONFIG_HEADER: &str =
    "# Generated by horus from [rust].rustflags in horus.toml — do not edit manually.";

/// Write `.cargo/config.toml` for `[rust].rustflags`, or remove it.
///
/// `rustflags` is the one `[rust]` key that cannot ride the manifest
/// passthrough: Cargo.toml has no slot for it. Cargo's supported homes are the
/// `RUSTFLAGS` environment variable — which only the process spawning cargo can
/// set, and this module does not spawn it — and `[build] rustflags` in a cargo
/// config file.
///
/// WHY THE PROJECT ROOT AND NOT `.horus/`. Cargo discovers config by walking up
/// from its *working directory*, not from `--manifest-path`. The first version
/// of this wrote `.horus/.cargo/config.toml`, reasoning that every build runs
/// with `.horus` as its cwd — true of `run_rust.rs` and `test.rs`, and false of
/// everything else. `horus lint`, `horus doc`, `horus bench` and the workspace
/// build all spawn cargo from the project root with `--manifest-path
/// .horus/Cargo.toml`, so the flags never reached them:
///
/// ```text
/// $ horus build   # [rust] rustflags = ["--bogus-horus-flag"]
/// error: Unrecognized option: 'bogus-horus-flag'
/// $ horus lint
///     Finished `dev` profile [unoptimized + debuginfo] target(s) in 26.68s
/// ```
///
/// A flag that applies to three commands and not the other four is worse than
/// one that applies to none: `horus lint` then compiles a different crate than
/// `horus build` does, and any `--cfg` disagreement shows up as errors in one
/// and not the other. The project root is the one directory every one of those
/// spawns sits in or under, so it is the only location that makes the setting
/// mean one thing. It is also where a Rust developer would look for it.
///
/// WHAT PROTECTS THE USER'S OWN CONFIG. `.horus/` is entirely ours; the project
/// root is not, and a cross-compiling robotics project may well already keep a
/// `.cargo/config.toml` full of linker settings. Overwriting it would be the
/// same silent destruction of a hand-written file that this module exists to
/// stop, so a config HORUS did not write is never touched — the flags fall back
/// to `.horus/` and the user is told which commands that leaves uncovered.
///
/// Exactly one of the two files exists at a time. Cargo *joins* array values
/// from every config it finds on the way up, so a leftover `.horus/` copy would
/// hand rustc every flag twice.
///
/// Removed rather than left in place when `rustflags` is emptied: a stale file
/// would keep applying flags `horus.toml` no longer asks for, which is the same
/// divergence between manifest and build that `[rust]` exists to end.
fn write_cargo_config(
    project_dir: &Path,
    horus_dir: &Path,
    rust: Option<&crate::manifest::RustConfig>,
) -> Result<()> {
    let root_config = project_dir.join(".cargo").join("config.toml");
    let build_config = horus_dir.join(".cargo").join("config.toml");

    let flags: &[String] = rust.map(|r| r.rustflags.as_slice()).unwrap_or(&[]);

    // A project with its own root `Cargo.toml` builds from that manifest and
    // not from the generated one, and `[rust]` is documented as having no
    // effect there — `run_rust.rs` warns about it by name. Writing a config
    // into the root would quietly apply the flags to the user's own cargo
    // builds while the tool is saying the section does nothing, which is the
    // same disagreement between message and behaviour that the workspace
    // warning was refuted over. Nothing is written, and the warning stays true.
    let horus_owns_the_build = !project_dir.join("Cargo.toml").exists();

    if flags.is_empty() || !horus_owns_the_build {
        remove_generated_cargo_config(&root_config)?;
        remove_generated_cargo_config(&build_config)?;
        return Ok(());
    }

    if root_cargo_config_is_ours_to_write(&root_config) {
        write_generated_cargo_config(&root_config, flags)?;
        remove_generated_cargo_config(&build_config)?;
    } else {
        write_generated_cargo_config(&build_config, flags)?;
        crate::cli_output::warn(
            "horus.toml sets [rust].rustflags, but this project already has a \
             .cargo config HORUS did not write, so it is left alone. The flags \
             went to .horus/.cargo/config.toml, which `horus build`, `horus run` \
             and `horus test` read — `horus lint`, `horus doc` and `horus bench` \
             run cargo from the project root and will not see them. Add the \
             flags to your own .cargo config to cover those too.",
        );
    }
    Ok(())
}

/// Whether the project root's cargo config is HORUS's to write.
///
/// `writable_by_horus`, plus the file cargo still reads under its pre-1.39
/// name. Cargo accepts both `.cargo/config.toml` and `.cargo/config`, and when
/// both exist it uses `config.toml` and ignores the other — so writing ours
/// next to a user's `config` would not overwrite their settings, it would
/// silently switch all of them off, which is worse.
fn root_cargo_config_is_ours_to_write(root_config: &Path) -> bool {
    let legacy_name = root_config.with_file_name("config");
    !legacy_name.exists() && writable_by_horus(root_config)
}

/// Write one cargo config, creating (and gitignoring) its directory.
fn write_generated_cargo_config(config_path: &Path, flags: &[String]) -> Result<()> {
    let config_dir = config_path.parent().unwrap_or(Path::new("."));
    let created_dir = !config_dir.exists();
    fs::create_dir_all(config_dir)
        .with_context(|| format!("Failed to create {}", config_dir.display()))?;

    let mut text = String::with_capacity(256);
    writeln!(
        text,
        "{GENERATED_CARGO_CONFIG_HEADER}\n\
         # Edits are lost on the next build; change [rust].rustflags instead."
    )
    .unwrap();
    writeln!(text, "[build]").unwrap();
    // Rendered through toml::Value so a flag containing a quote or a backslash
    // is escaped by the serializer rather than by this format string.
    writeln!(text, "rustflags = {}", toml::Value::from(flags.to_vec())).unwrap();

    fs::write(config_path, text)
        .with_context(|| format!("Failed to write {}", config_path.display()))?;

    // Only when HORUS created the directory: an existing `.cargo/` is the
    // user's, and hiding it from git is not ours to decide.
    if created_dir {
        ignore_generated_dir(config_dir, CARGO_CONFIG_DIR_IS_GENERATED);
    }
    Ok(())
}

/// Delete a cargo config, but only one HORUS generated.
fn remove_generated_cargo_config(config_path: &Path) -> Result<()> {
    if !generated_by_horus(config_path) {
        return Ok(());
    }
    fs::remove_file(config_path)
        .with_context(|| format!("Failed to remove {}", config_path.display()))?;
    Ok(())
}

/// Whether this cargo config carries the header HORUS writes.
fn generated_by_horus(config_path: &Path) -> bool {
    fs::read_to_string(config_path)
        .is_ok_and(|text| text.starts_with(GENERATED_CARGO_CONFIG_HEADER))
}

/// Whether HORUS may write this cargo config: nothing is there, or what is
/// there is a file HORUS wrote.
fn writable_by_horus(config_path: &Path) -> bool {
    !config_path.exists() || generated_by_horus(config_path)
}

/// Write driver dependencies from `[drivers]` config tables.
///
/// For each `[drivers.NAME]` entry:
/// - `terra = "dynamixel"` → adds `terra-serial = { version = "0.2", features = ["dynamixel"] }`
/// - `package = "horus-driver-x"` → adds `horus-driver-x = "*"`
/// - `node = "MyDriver"` → no dependency (local code)
/// - `camera = "opencv"` / `gps = true` → no dependency (legacy, handled by feature flags)
fn write_driver_deps(
    cargo: &mut String,
    drivers: &std::collections::BTreeMap<String, crate::manifest::DriverValue>,
) {
    use crate::manifest::DriverValue;

    // Track crates already added to avoid duplicates (e.g., two drivers using terra-serial).
    // Value = (explicit version if the driver pinned one, features). A BTreeMap keeps the
    // generated dependency lines in deterministic order (the old HashMap produced
    // run-to-run line reshuffling → spurious diffs / non-reproducible Cargo.toml).
    let mut added_crates: BTreeMap<String, (Option<String>, Vec<String>)> = BTreeMap::new();

    for value in drivers.values() {
        match value {
            DriverValue::Config(cfg) => {
                // Terra drivers: no longer auto-resolved — user adds terra-horus
                // as a normal dependency in [dependencies]. Skip terra entries.
                if let Some(package) = &cfg.package {
                    // Registry package — version resolved at install time, emit as "*".
                    added_crates
                        .entry(package.clone())
                        .or_insert((None, Vec::new()));
                } else if let Some(crate_name) = &cfg.crate_name {
                    // CratesIo driver — add the crate, PRESERVING any pinned version.
                    // Previously the version was extracted then discarded, so a driver
                    // that pinned `version = "1.2"` still emitted a bare `crate = "*"`.
                    let version = cfg
                        .params
                        .get("version")
                        .and_then(|v| v.as_str())
                        .map(str::to_string);
                    let entry = added_crates
                        .entry(crate_name.clone())
                        .or_insert((None, Vec::new()));
                    if entry.0.is_none() {
                        entry.0 = version;
                    }
                }
                // pip/exec/sim3d/node → no Cargo dep needed
            }
            DriverValue::Backend(_) | DriverValue::Enabled(_) => {
                // Legacy — handled by feature flags in get_cargo_features_from_drivers()
            }
        }
    }

    if !added_crates.is_empty() {
        writeln!(cargo, "\n# Driver dependencies (from [drivers])").unwrap();
        for (crate_name, (version, features)) in &added_crates {
            let ver = version.as_deref().unwrap_or("*");
            if features.is_empty() {
                writeln!(cargo, "{} = \"{}\"", crate_name, ver).unwrap();
            } else {
                let features_str = features
                    .iter()
                    .map(|f| format!("\"{}\"", f))
                    .collect::<Vec<_>>()
                    .join(", ");
                writeln!(
                    cargo,
                    "{} = {{ version = \"{}\", features = [{}] }}",
                    crate_name, ver, features_str
                )
                .unwrap();
            }
        }
    }
}

/// Write a `[[bin]]` entry.
fn write_bin_entry(cargo: &mut String, name: &str, path: &str) {
    writeln!(cargo, "[[bin]]").unwrap();
    writeln!(cargo, "name = \"{}\"", sanitize_cargo_name(name)).unwrap();
    writeln!(cargo, "path = \"{}\"", path).unwrap();
    writeln!(cargo).unwrap();
}

/// Write horus core/library/macros path dependencies.
/// Write implicit dependencies every HORUS project needs but that are not
/// declared in horus.toml.
///
/// serde: the canonical `message!` macro and the documented
/// `#[derive(Serialize, Deserialize)]` pattern both expand to `serde::Serialize`
/// / `serde::Deserialize`, so serde must be a *direct* dependency of the user's
/// crate — it is not enough for horus to depend on it transitively. Without this
/// a fresh project using `message!` fails to compile with
/// "cannot find crate `serde`", contradicting the macro's "zero configuration"
/// promise. Skipped if the user declared serde themselves.
fn write_implicit_deps(cargo: &mut String, manifest: &HorusManifest) {
    if !manifest.dependencies.contains_key("serde") {
        writeln!(
            cargo,
            "serde = {{ version = \"1\", features = [\"derive\"] }}"
        )
        .unwrap();
    }
}

/// Features to enable on the `horus` dependency.
///
/// `horus run --net` used to set `HORUS_NET=1` and stop there. That variable is
/// read in exactly one place — `horus doctor` — and the `net` Cargo feature is
/// not in `default`, so nothing ever enabled it: the built binary contained no
/// horus_net symbols at all. A developer wiring two robots saw a normal run
/// with zero networking output and concluded multicast was blocked, while
/// 10.8k lines of horus_net sat unreachable behind the flag that advertises it.
///
/// It belongs here rather than in `--features`, which applies to the *user's*
/// crate: cargo rejects `--features net` with "the package does not contain
/// this feature".
fn horus_dep_features(manifest: &HorusManifest) -> Vec<String> {
    // Driver names used to be mapped to Cargo features here:
    //
    //     "camera" => Some("camera"), "lidar" => Some("lidar"),
    //     "imu"    => Some("imu"),    "gps"   => Some("gps"),
    //
    // `horus` has five features — blackbox, default, macros, net, telemetry —
    // and has never had any of those four. So declaring a driver under one of
    // those four names generated a manifest cargo refuses:
    //
    //     error: failed to select a version for `horus`.
    //     package `driver_integration` depends on `horus` with feature `imu`
    //     but `horus` does not have that feature.
    //
    // `[drivers]` is the documented way to declare hardware, and `imu`, `lidar`,
    // `camera` and `gps` are the four names most likely to be used, so the
    // documented workflow failed for exactly the common cases. The shipped
    // `driver_integration` example is one of them and did not build.
    //
    // Driver *dependencies* are handled by `write_driver_deps`; nothing about a
    // driver needs a feature on `horus`.
    let mut features: Vec<String> = Vec::new();

    let requested_net = std::env::var("HORUS_ENABLE")
        .map(|v| {
            v.split(',')
                .any(|c| matches!(c.trim().to_lowercase().as_str(), "net" | "network"))
        })
        .unwrap_or(false)
        || manifest
            .enable
            .iter()
            .any(|c| matches!(c.to_lowercase().as_str(), "net" | "network"));

    if requested_net && !features.iter().any(|f| f == "net") {
        features.push("net".to_string());
    }
    features
}

/// Depend on the crate `horus msg gen` produced, when there is one.
///
/// Without this the generated types compile in isolation and are reachable from
/// nothing — the same shape as the Python generator that wrote Rust into a
/// directory `lib.rs` never declared, where cargo compiled none of it and
/// nothing reported an error anywhere.
fn write_generated_msgs_dep(cargo: &mut String, project_dir: &Path, manifest: &HorusManifest) {
    let generated = project_dir.join(".horus/generated/msgs");
    if !generated.join("Cargo.toml").is_file() {
        return;
    }
    writeln!(
        cargo,
        "{}_msgs = {{ path = \"{}\" }}",
        sanitize_cargo_name(&manifest.package.name),
        generated.display()
    )
    .unwrap();
}

fn write_horus_path_deps(cargo: &mut String, horus_source: &Path, manifest: &HorusManifest) {
    // Detect hardware features from manifest
    let hw_features: Vec<String> = horus_dep_features(manifest);

    for dep_name in &["horus", "horus_core", "horus_library", "horus_macros"] {
        let dep_path = horus_source.join(dep_name);
        if dep_path.exists() && dep_path.join("Cargo.toml").exists() {
            if (*dep_name == "horus" || *dep_name == "horus_library") && !hw_features.is_empty() {
                writeln!(
                    cargo,
                    "{} = {{ path = \"{}\", features = [{}] }}",
                    dep_name,
                    dep_path.display(),
                    hw_features
                        .iter()
                        .map(|f| format!("\"{}\"", f))
                        .collect::<Vec<_>>()
                        .join(", ")
                )
                .unwrap();
            } else {
                writeln!(
                    cargo,
                    "{} = {{ path = \"{}\" }}",
                    dep_name,
                    dep_path.display()
                )
                .unwrap();
            }
        }
    }
}

/// Git repos whose packages reference `horus_core` and friends by relative path,
/// and the crates each one needs redirected at the local source tree.
///
/// Mirrors the `[patch]` tables in the root workspace `Cargo.toml`. Kept in sync
/// by `patch_sections_match_root_workspace` in the tests below.
const GIT_PATCH_TARGETS: &[(&str, &[&str])] = &[
    (
        "https://github.com/softmata/horus-robotics.git",
        &["horus_core", "horus_types", "horus_macros"],
    ),
    (
        "https://github.com/softmata/horus-tf.git",
        &["horus_core", "horus_macros"],
    ),
];

/// The edition a manifest asks for, if it asks for one at all.
///
/// `[rust].edition` beats `[package].rust_edition`. Kept separate from the
/// default below because a workspace member that names no edition has one more
/// place to look — the workspace root — and "the user wrote 2021" and "nobody
/// wrote anything" have to stay distinguishable for that.
fn explicit_edition(manifest: &HorusManifest) -> Option<String> {
    manifest
        .rust
        .as_ref()
        .and_then(|r| r.edition.clone())
        .or_else(|| manifest.package.rust_edition.clone())
}

/// The Rust edition for the generated package.
///
/// `[rust].edition` beats `[package].rust_edition`, which beats the 2021
/// default. Both paths that emit an edition use this, so they cannot drift.
fn rust_edition(manifest: &HorusManifest) -> String {
    explicit_edition(manifest).unwrap_or_else(|| "2021".to_string())
}

/// The Rust edition for a workspace member.
///
/// The root's edition is the workspace-wide default, the way cargo's
/// `[workspace.package] edition` is: a member that names its own wins, and a
/// member that names none inherits rather than silently falling back to 2021.
/// Nothing read the root's `[rust].edition` on the workspace path before —
/// `generate_workspace` only ever asked the member — so setting an edition at
/// the root of a workspace did nothing at all.
fn member_edition(member: &HorusManifest, root: &HorusManifest) -> String {
    explicit_edition(member)
        .or_else(|| explicit_edition(root))
        .unwrap_or_else(|| "2021".to_string())
}

/// The `[rust]` tables a standalone package manifest carries: all of them.
const PACKAGE_RUST_SECTIONS: &[&str] = &[
    "features",
    "build-dependencies",
    "lints",
    "profile",
    "target",
];

/// The `[rust]` tables a workspace *member* manifest carries.
///
/// `profile` is missing because cargo ignores a profile declared anywhere but
/// the workspace root ("profiles for the non root package will be ignored"),
/// and `patch` because the same is true of it — both are forwarded from the
/// root manifest instead, and a member that declares one is warned about by
/// `warn_about_rust_settings_a_workspace_cannot_place`.
const MEMBER_RUST_SECTIONS: &[&str] = &["features", "build-dependencies", "lints", "target"];

/// The `[rust]` tables the generated workspace *root* manifest carries.
///
/// Only `profile`: the root is a virtual manifest with no `[package]`, and
/// cargo rejects a virtual manifest carrying `[features]`, `[target]` or
/// `[build-dependencies]` rather than ignoring them. `patch` is written by
/// `write_patch_sections`, and `lints` goes to the members (see
/// `member_rust_section`).
const WORKSPACE_ROOT_RUST_SECTIONS: &[&str] = &["profile"];

/// Splice the user's `[rust]` tables into the generated manifest.
///
/// Built as a `toml` table and serialized in one call rather than written line
/// by line. Hand-writing it got two cases wrong that look identical in the
/// source: `[rust.lints.rust]` is a nested table and came out as an empty
/// `[lints]`, and `somecrate = { path = "..." }` is an *inline* table — which
/// `Value::is_table()` also reports as a table — so it was skipped as if it
/// were a section header. Letting the serializer decide removes the
/// distinction from this code entirely.
///
/// Only sections HORUS does not write itself, so there is nothing to merge and
/// nothing to lose. `[patch]` is the exception and is handled in
/// `write_patch_sections`, where HORUS's own entries have to win.
///
/// `sections` says which of the tables the manifest being written is allowed to
/// carry. A single-package manifest takes all of them; a workspace splits them,
/// because cargo reads `[profile]` only from the workspace root and
/// `[features]`, `[target]` and `[build-dependencies]` only from a package.
/// Writing one into the wrong manifest is not a no-op — cargo fails a virtual
/// workspace root that carries `[features]` outright — so the split is enforced
/// here rather than left to the caller to remember.
fn write_rust_passthrough(
    cargo: &mut String,
    rust: &crate::manifest::RustConfig,
    sections: &[&str],
) {
    let mut doc = toml::value::Table::new();
    for (name, table) in [
        ("features", &rust.features),
        ("build-dependencies", &rust.build_dependencies),
        ("lints", &rust.lints),
        ("profile", &rust.profile),
        ("target", &rust.target),
    ] {
        if !sections.contains(&name) {
            continue;
        }
        if let Some(table) = table {
            if !table.is_empty() {
                doc.insert(name.to_string(), toml::Value::Table(table.clone()));
            }
        }
    }
    if doc.is_empty() {
        return;
    }
    match toml::to_string(&toml::Value::Table(doc)) {
        Ok(text) => {
            writeln!(cargo).unwrap();
            cargo.push_str(&text);
        }
        // Never splice something that would not round-trip: a half-written
        // table would corrupt every section after it.
        Err(e) => log::warn!("[rust] section could not be serialized, ignoring it: {e}"),
    }
}

/// Write the `[patch]` tables that redirect git-sourced HORUS crates at the
/// local source tree, with the user's `[rust.patch]` merged in.
///
/// `horus-robotics` and `horus-tf` depend on `horus_core` (and siblings) through
/// relative paths that only resolve inside the HORUS checkout — a bare clone of
/// either git repo has no such package. The root workspace compensates with
/// `[patch."<git url>"]` tables.
///
/// A generated `.horus/Cargo.toml` declares its own `[workspace]`, which makes it
/// a *new* workspace root. Cargo only honors `[patch]` from the workspace root of
/// the build actually running and never inherits it through a path dependency, so
/// the root workspace's tables are dropped on the floor and the build dies with
/// `no matching package named 'horus_core' found`. Re-emitting them here is what
/// keeps a generated project buildable. `horus_cpp/fuzz/Cargo.toml` solves the
/// identical problem by hand for the same reason.
///
/// HORUS's own entries win a key collision and say so. They are load-bearing:
/// without them every generated project fails to resolve `horus_core`. Any
/// patch source HORUS does not claim passes through untouched.
///
/// Written by hand rather than through `toml::to_string`, which renders each
/// crate as its own `[patch."url".crate]` header. That is valid and equivalent,
/// but `crate = { path = "..." }` is what this file has always contained and is
/// far easier to read. `toml::Value`'s `Display` produces the inline form, so a
/// user-supplied entry of any shape renders correctly without this code having
/// to know what shape it is.
///
/// Must be called last: `[patch.*]` is a top-level table, so anything written
/// after it would be parsed as part of it rather than of `[dependencies]`.
fn write_patch_sections(
    cargo: &mut String,
    horus_source: &Path,
    rust: Option<&crate::manifest::RustConfig>,
) {
    let user_patch = rust.and_then(|r| r.patch.as_ref());
    let mut claimed: Vec<&str> = Vec::new();

    for (git_url, crates) in GIT_PATCH_TARGETS {
        // Only patch crates that exist locally — Cargo hard-errors on a patch
        // entry pointing at a nonexistent path.
        let present: Vec<&&str> = crates
            .iter()
            .filter(|name| horus_source.join(name).join("Cargo.toml").exists())
            .collect();
        if present.is_empty() {
            continue;
        }
        claimed.push(git_url);

        writeln!(cargo).unwrap();
        writeln!(cargo, "[patch.\"{}\"]", git_url).unwrap();
        for name in &present {
            writeln!(
                cargo,
                "{} = {{ path = \"{}\" }}",
                name,
                horus_source.join(name).display()
            )
            .unwrap();
        }
        // The user may add crates to a source HORUS also patches, but not
        // replace the ones HORUS needs.
        if let Some(entries) = user_patch
            .and_then(|p| p.get(*git_url))
            .and_then(|v| v.as_table())
        {
            for (key, value) in entries {
                if present.iter().any(|n| **n == key.as_str()) {
                    log::warn!(
                        "[rust.patch.\"{git_url}\"].{key} is overridden by HORUS's own patch"
                    );
                    continue;
                }
                writeln!(cargo, "{key} = {value}").unwrap();
            }
        }
    }

    // Patch sources HORUS does not claim.
    if let Some(user_patch) = user_patch {
        for (source, entries) in user_patch {
            if claimed.contains(&source.as_str()) {
                continue; // merged above
            }
            let Some(entries) = entries.as_table() else {
                continue;
            };
            writeln!(cargo).unwrap();
            writeln!(cargo, "[patch.\"{source}\"]").unwrap();
            for (key, value) in entries {
                writeln!(cargo, "{key} = {value}").unwrap();
            }
        }
    }
}

/// Write dependencies from a BTreeMap to Cargo.toml format.
///
/// Filters for Rust-compatible deps: crates.io, path, git.
/// Registry deps are resolved to path deps pointing to .horus/packages/.
/// PyPI and System deps are skipped (not relevant for Cargo).
///
/// For Simple deps that default to Registry, the smart source resolver is
/// consulted — if the package is a well-known crate, it's treated as crates.io.
fn write_deps_section(
    cargo: &mut String,
    deps: &std::collections::BTreeMap<String, DependencyValue>,
    project_dir: &Path,
    horus_dir: &Path,
) -> Result<()> {
    use crate::manifest::Language;
    use crate::source_resolver::PackageSourceResolver;
    let resolver = PackageSourceResolver::new(&[Language::Rust]);

    for (name, dep) in deps {
        let source = match dep.effective_source() {
            DepSource::Registry => {
                // Simple deps default to Registry — use smart resolver to check
                // if it's actually a well-known crates.io package.
                // Only upgrade with High confidence to avoid false positives.
                let resolved = resolver.resolve(name);
                if resolved.confidence == crate::source_resolver::Confidence::High {
                    resolved.source
                } else {
                    DepSource::Registry
                }
            }
            other => other,
        };
        match source {
            DepSource::CratesIo => {
                write_crates_io_dep(cargo, name, dep);
            }
            DepSource::Path => {
                if let DependencyValue::Detailed(d) = dep {
                    if let Some(ref p) = d.path {
                        // Resolve path relative to project dir, then make relative to .horus/
                        let abs_path = project_dir.join(p);
                        let rel = relative_to_horus(&abs_path, horus_dir);
                        writeln!(cargo, "{} = {{ path = \"{}\" }}", name, rel).unwrap();
                    }
                }
            }
            DepSource::Git => {
                if let DependencyValue::Detailed(d) = dep {
                    write_git_dep(cargo, name, d);
                }
            }
            DepSource::Registry => {
                // Registry packages are installed to .horus/packages/<name>/
                // If the package dir exists, add as path dep
                let pkg_dir = horus_dir.join("packages").join(name);
                if pkg_dir.exists() && pkg_dir.join("Cargo.toml").exists() {
                    writeln!(cargo, "{} = {{ path = \"packages/{}\" }}", name, name).unwrap();
                } else {
                    writeln!(
                        cargo,
                        "# {} = \"{}\" (registry, not yet installed)",
                        name,
                        dep.version().unwrap_or("*")
                    )
                    .unwrap();
                }
            }
            DepSource::PyPI | DepSource::System => {
                // Not Cargo deps — skip silently
            }
        }
    }
    Ok(())
}

/// Auto-install missing registry dependencies before Cargo.toml generation.
///
/// Scans the dependency map for `DepSource::Registry` entries, checks if each
/// is already present in `.horus/packages/<name>/`, and silently installs any
/// that are missing from the horus registry. This ensures `write_deps_section`
/// can emit real path deps instead of commented-out placeholders.
///
/// Failures are logged as warnings — the build continues and cargo will report
/// the missing crate with a clear error if auto-install didn't succeed.
fn auto_install_registry_deps(
    deps: &BTreeMap<String, DependencyValue>,
    project_dir: &Path,
    horus_dir: &Path,
) -> Result<()> {
    use crate::manifest::Language;
    use crate::source_resolver::PackageSourceResolver;

    let resolver = PackageSourceResolver::new(&[Language::Rust]);
    let mut missing: Vec<(String, Option<String>)> = Vec::new();

    for (name, dep) in deps {
        let source = match dep.effective_source() {
            DepSource::Registry => {
                let resolved = resolver.resolve(name);
                if resolved.confidence == crate::source_resolver::Confidence::High {
                    resolved.source
                } else {
                    DepSource::Registry
                }
            }
            other => other,
        };

        if source == DepSource::Registry {
            let pkg_dir = horus_dir.join("packages").join(name);
            if !pkg_dir.exists() || !pkg_dir.join("Cargo.toml").exists() {
                missing.push((name.clone(), dep.version().map(String::from)));
            }
        }
    }

    if missing.is_empty() {
        return Ok(());
    }

    eprintln!(
        "  {} Auto-installing {} registry package(s)...",
        crate::cli_output::ICON_INFO.cyan(),
        missing.len()
    );

    let client = crate::registry::RegistryClient::new();
    let target = crate::workspace::InstallTarget::Local(project_dir.to_path_buf());

    for (name, version) in &missing {
        eprintln!("    {} {}...", "v".cyan(), name);
        match client.install_from_registry(name, version.as_deref(), target.clone()) {
            Ok(v) => {
                eprintln!(
                    "    {} {} v{}",
                    crate::cli_output::ICON_SUCCESS.green(),
                    name,
                    v
                );
            }
            Err(e) => {
                // Warn but don't fail — cargo build will give a clear error
                eprintln!(
                    "    {} Failed to auto-install {}: {}",
                    crate::cli_output::ICON_WARN.yellow(),
                    name,
                    e
                );
            }
        }
    }

    Ok(())
}

/// Write a crates.io dependency line.
fn write_crates_io_dep(cargo: &mut String, name: &str, dep: &DependencyValue) {
    match dep {
        DependencyValue::Simple(v) => {
            writeln!(cargo, "{} = \"{}\"", name, v).unwrap();
        }
        DependencyValue::Detailed(d) => {
            let version = d.version.as_deref().unwrap_or("*");
            if d.features.is_empty() && !d.optional {
                writeln!(cargo, "{} = \"{}\"", name, version).unwrap();
            } else {
                let mut parts = vec![format!("version = \"{}\"", version)];
                if !d.features.is_empty() {
                    let feats = d
                        .features
                        .iter()
                        .map(|f| format!("\"{}\"", f))
                        .collect::<Vec<_>>()
                        .join(", ");
                    parts.push(format!("features = [{}]", feats));
                }
                if d.optional {
                    parts.push("optional = true".to_string());
                }
                writeln!(cargo, "{} = {{ {} }}", name, parts.join(", ")).unwrap();
            }
        }
    }
}

/// Write a git dependency line.
fn write_git_dep(cargo: &mut String, name: &str, d: &crate::manifest::DetailedDependency) {
    let git_url = d.git.as_deref().unwrap_or("");
    let mut parts = vec![format!("git = \"{}\"", git_url)];
    if let Some(ref branch) = d.branch {
        parts.push(format!("branch = \"{}\"", branch));
    }
    if let Some(ref tag) = d.tag {
        parts.push(format!("tag = \"{}\"", tag));
    }
    if let Some(ref rev) = d.rev {
        parts.push(format!("rev = \"{}\"", rev));
    }
    writeln!(cargo, "{} = {{ {} }}", name, parts.join(", ")).unwrap();
}

/// Compute a relative path from `.horus/` to a file.
///
/// e.g., `/home/user/project/main.rs` from `/home/user/project/.horus/`
/// → `../main.rs`
fn relative_to_horus(file: &Path, horus_dir: &Path) -> String {
    // Try to compute relative path
    if let Ok(rel) = pathdiff(file, horus_dir) {
        rel
    } else {
        // Fallback to absolute
        file.to_string_lossy().to_string()
    }
}

/// Simple relative path computation (from -> to).
fn pathdiff(target: &Path, base: &Path) -> Result<String, ()> {
    // Canonicalize if possible, otherwise use as-is
    let target = target
        .canonicalize()
        .unwrap_or_else(|_| target.to_path_buf());
    let base = base.canonicalize().unwrap_or_else(|_| base.to_path_buf());

    let mut target_parts: Vec<_> = target.components().collect();
    let mut base_parts: Vec<_> = base.components().collect();

    // Remove common prefix
    while !target_parts.is_empty() && !base_parts.is_empty() && target_parts[0] == base_parts[0] {
        target_parts.remove(0);
        base_parts.remove(0);
    }

    // Go up for remaining base parts, then down for target parts
    let mut result = String::new();
    for _ in &base_parts {
        if !result.is_empty() {
            result.push('/');
        }
        result.push_str("..");
    }
    for part in &target_parts {
        if !result.is_empty() {
            result.push('/');
        }
        result.push_str(&part.as_os_str().to_string_lossy());
    }

    if result.is_empty() {
        result.push('.');
    }

    Ok(result)
}

/// Sanitize a name for use as a Cargo package/bin name.
///
/// Replaces characters that are invalid in Cargo names with underscores.
pub fn sanitize_cargo_name(name: &str) -> String {
    name.chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '_' || c == '-' {
                c
            } else {
                '_'
            }
        })
        .collect()
}

// ─── Workspace generation ────────────────────────────────────────────────────

use crate::manifest::{resolve_workspace_members, TargetType};
/// Outcome of [`ensure`], so callers can tell "nothing to do" from "it broke".
#[derive(Debug, PartialEq, Eq)]
pub enum Ensured {
    /// `.horus/Cargo.toml` was written (or rewritten).
    Generated,
    /// Nothing to generate — not a Rust project with an entry point.
    Skipped,
    /// Generation was attempted and failed. Carries the reason for the caller
    /// to surface; never fatal.
    Failed(String),
}

/// Make `.horus/Cargo.toml` exist, best-effort and never fatal.
///
/// WHY THIS EXISTS. `.horus/Cargo.toml` is the only cargo manifest a template
/// project has, and until now it was written exclusively by `horus build` and
/// `horus run`. Before the first build there is no manifest anywhere, so
/// rust-analyzer has no project to load at all — it reports
/// `failed to find any projects` and offers zero IDE services on `src/main.rs`.
/// The generated `.gitignore` also lists `.horus/Cargo.toml`, so a fresh clone
/// of a HORUS project lands in the same state. Nothing told the user that a
/// build is what turns the IDE on.
///
/// Generating it at `horus new` time closes that. Note what this deliberately
/// is NOT: it is not a build, it does not resolve dependencies, and it does not
/// touch the network. On the `horus new` path `horus.toml` has no dependencies
/// yet, so `auto_install_registry_deps` returns at its `missing.is_empty()`
/// guard before any resolver runs.
///
/// FAILURE IS NOT FATAL, BY DESIGN. [`generate`] hard-fails when the HORUS
/// source tree cannot be found, because for a *build* that is the actionable
/// error. For `horus new` it is not: the project is already valid on disk, and
/// aborting scaffolding over a missing IDE convenience would be a regression.
/// Callers get [`Ensured::Failed`] and decide what to say.
pub fn ensure(project_dir: &Path) -> Ensured {
    let manifest_path = project_dir.join(crate::manifest::HORUS_TOML);
    let Ok(manifest) = crate::manifest::HorusManifest::load_from(&manifest_path) else {
        return Ensured::Skipped;
    };

    // A workspace generates a root plus one manifest per member; entry-point
    // probing happens per member inside generate_workspace.
    if !manifest.is_workspace() {
        // `generate` picks the `[[bin]]` by probing these two paths, and emits
        // no target at all when neither exists (a `--lib` project, or Python or
        // C++). A manifest with no target is worse than no manifest: cargo would
        // look for `.horus/src/lib.rs`, which does not exist, and rust-analyzer
        // reports a hard load error instead of simply having nothing to load.
        let has_entry =
            project_dir.join("main.rs").exists() || project_dir.join("src/main.rs").exists();
        if !has_entry {
            return Ensured::Skipped;
        }
    }

    match generate_for_manifest(&manifest, project_dir, &[], false) {
        Ok(_) => Ensured::Generated,
        Err(e) => Ensured::Failed(format!("{e:#}")),
    }
}

/// Whether `.horus/Cargo.toml` exists but points at a HORUS source tree that is
/// no longer there.
///
/// The generated manifest bakes in an ABSOLUTE path, resolved once by
/// `find_horus_source_dir()`. That path is not stable for the lifetime of the
/// project. The resolver's last resort is the installer cache, keyed by version
/// as `<cache>/horus@<version>`, so `horus upgrade` renames the directory every
/// project was pointing at — invalidating all of them at once.
///
/// A stale manifest is a WORSE failure than a missing one. Missing means
/// rust-analyzer has nothing to load; stale means `cargo metadata` dies with
///
/// ```text
/// error: failed to load manifest for dependency `horus`
/// Caused by: failed to read /…/horus@0.2.2/horus/Cargo.toml
/// ```
///
/// and the editor reports a workspace-load failure. `horus build` already
/// repairs this because it regenerates unconditionally, but a user whose editor
/// broke after an upgrade has no reason to think "run a build" is the fix — so
/// the cheap recovery commands should repair it too.
///
/// Detection is deliberately shallow: read the generated file, pull out the
/// `path = "…"` values, and report true if any names a directory that does not
/// exist. That catches the upgrade case and a moved or deleted checkout without
/// re-running dependency resolution.
pub fn is_stale(project_dir: &Path) -> bool {
    let generated = project_dir.join(HORUS_DIR).join("Cargo.toml");
    let Ok(text) = fs::read_to_string(&generated) else {
        return false;
    };

    for line in text.lines() {
        let Some(rest) = line.split("path = \"").nth(1) else {
            continue;
        };
        let Some(raw) = rest.split('"').next() else {
            continue;
        };
        let path = Path::new(raw);
        // Relative entries are the project's own sources (`../src/main.rs`),
        // resolved against `.horus/`; absolute ones are the HORUS source tree.
        if path.is_absolute() && !path.exists() {
            log::debug!("generated manifest points at a missing path: {raw}");
            return true;
        }
    }
    false
}

/// Smart dispatcher: routes to single-package or workspace generation.
///
/// If the manifest has `[workspace]`, generates a Cargo workspace.
/// Otherwise, falls through to the existing single-package `generate()`.
pub fn generate_for_manifest(
    manifest: &HorusManifest,
    project_dir: &Path,
    source_files: &[PathBuf],
    include_dev: bool,
) -> Result<(PathBuf, String)> {
    if let Some(ref ws) = manifest.workspace {
        let members = resolve_workspace_members(ws, project_dir)?;
        generate_workspace(manifest, project_dir, &members)
    } else {
        generate(manifest, project_dir, source_files, include_dev)
    }
}

/// Generate a Cargo workspace from a multi-member horus workspace.
///
/// Produces:
/// - `.horus/Cargo.toml` with `[workspace]` section
/// - `.horus/{member_name}/Cargo.toml` for each member
///
/// Returns the root path and its content for fingerprinting.
pub fn generate_workspace(
    root_manifest: &HorusManifest,
    project_dir: &Path,
    members: &[(PathBuf, HorusManifest)],
) -> Result<(PathBuf, String)> {
    let horus_dir = project_dir.join(HORUS_DIR);
    fs::create_dir_all(&horus_dir).context("Failed to create .horus directory")?;

    // ── Auto-install missing registry deps (workspace + all members) ─────
    if let Some(ref ws) = root_manifest.workspace {
        if !ws.dependencies.is_empty() {
            auto_install_registry_deps(&ws.dependencies, project_dir, &horus_dir)?;
        }
    }
    for (_, member_manifest) in members {
        if !member_manifest.dependencies.is_empty() {
            auto_install_registry_deps(&member_manifest.dependencies, project_dir, &horus_dir)?;
        }
    }

    warn_about_rust_settings_a_workspace_cannot_place(root_manifest, members);

    // Loaded once and saved once at the end: the root and every member are
    // written through the same fingerprint set, and reloading it per file would
    // make each write blind to the ones before it.
    let mut fingerprints = crate::fingerprint::Fingerprints::load(project_dir).unwrap_or_default();

    let mut root_cargo = String::with_capacity(2048);

    // ── Header ────────────────────────────────────────────────────────────
    writeln!(
        root_cargo,
        "# Generated by horus from horus.toml — do not edit manually.\n\
         # Edits are lost on the next build."
    )
    .unwrap();

    // ── Workspace section ─────────────────────────────────────────────────
    writeln!(root_cargo, "[workspace]").unwrap();
    writeln!(root_cargo, "resolver = \"2\"").unwrap();

    // Members list — use sanitized package names as directory names within .horus/
    let member_names: Vec<String> = members
        .iter()
        .map(|(_, m)| sanitize_cargo_name(&m.package.name))
        .collect();
    write!(root_cargo, "members = [").unwrap();
    for (i, name) in member_names.iter().enumerate() {
        if i > 0 {
            write!(root_cargo, ", ").unwrap();
        }
        write!(root_cargo, "\"{}\"", name).unwrap();
    }
    writeln!(root_cargo, "]").unwrap();
    writeln!(root_cargo).unwrap();

    // ── Workspace dependencies ────────────────────────────────────────────
    let ws = root_manifest.workspace.as_ref();
    let ws_deps = ws.map(|w| &w.dependencies);

    // Resolved once here: also needed by write_patch_sections below.
    let horus_source = crate::commands::run::find_horus_source_dir()
        .context("Cannot generate .horus/Cargo.toml workspace without the HORUS source tree")?;

    // Always write [workspace.dependencies] to include horus core deps
    {
        writeln!(root_cargo, "[workspace.dependencies]").unwrap();

        // Auto-inject horus core path deps. Required — see the note on the
        // single-package path above; an empty section yields unresolvable
        // imports in every workspace member.
        {
            for dep_name in &["horus", "horus_core", "horus_library", "horus_macros"] {
                let dep_path = horus_source.join(dep_name);
                if dep_path.exists() && dep_path.join("Cargo.toml").exists() {
                    writeln!(
                        root_cargo,
                        "{} = {{ path = \"{}\" }}",
                        dep_name,
                        dep_path.display()
                    )
                    .unwrap();
                }
            }
            // serde is implicit — see write_implicit_deps. Members opt in via
            // `serde = { workspace = true }` (added in generate_member_cargo).
            //
            // Skipped when the workspace declares its own: writing both put
            // `serde` in `[workspace.dependencies]` twice, and a duplicate key
            // is not a TOML document at all — cargo rejects the whole manifest
            // with "duplicate key `serde`". `generate_member_cargo` has always
            // made the same check for a member's own `[dependencies]`; the root
            // had diverged. Only visible once something parsed the generated
            // root as TOML instead of grepping it for substrings.
            if !ws_deps.is_some_and(|deps| deps.contains_key("serde")) {
                writeln!(
                    root_cargo,
                    "serde = {{ version = \"1\", features = [\"derive\"] }}"
                )
                .unwrap();
            }
        }

        // User workspace deps
        if let Some(deps) = ws_deps {
            write_deps_section(&mut root_cargo, deps, project_dir, &horus_dir)?;
        }
        writeln!(root_cargo).unwrap();
    }

    // ── If root also has a [package], include it as a member ──────────────
    if !root_manifest.package.name.is_empty() {
        // Root package goes into .horus/ directly (uses the root's source files)
        // For now, root packages in workspace mode use the single-package generate()
        // which already writes to .horus/Cargo.toml — skip for virtual workspaces.
    }

    // ── Generate per-member Cargo.toml ────────────────────────────────────
    for (rel_path, member_manifest) in members {
        let member_name = sanitize_cargo_name(&member_manifest.package.name);
        let member_horus_dir = horus_dir.join(&member_name);
        fs::create_dir_all(&member_horus_dir)
            .with_context(|| format!("Failed to create .horus/{}", member_name))?;

        let member_source_dir = project_dir.join(rel_path);
        let member_cargo = generate_member_cargo(
            &member_name,
            member_manifest,
            &member_source_dir,
            &member_horus_dir,
            root_manifest,
            members,
            &horus_dir,
        )?;

        let member_cargo_path = member_horus_dir.join("Cargo.toml");
        write_generated(
            project_dir,
            &format!("{}/Cargo.toml", member_name),
            &member_cargo_path,
            &member_cargo,
            &mut fingerprints,
            &sections_horus_toml_keeps(member_manifest),
        )?;
    }

    // ── [rust] passthrough ───────────────────────────────────────────────
    // Only `[profile]`, and only here: cargo reads profiles from the workspace
    // root and ignores (with a warning of its own) any a member declares. The
    // member-level tables are written into the member manifests instead, and a
    // virtual workspace root cannot carry them at all — cargo rejects the whole
    // manifest for it.
    if let Some(rust) = &root_manifest.rust {
        write_rust_passthrough(&mut root_cargo, rust, WORKSPACE_ROOT_RUST_SECTIONS);
    }

    // ── Patch tables ─────────────────────────────────────────────────────
    // Last: [patch.*] is a top-level table and would swallow later entries.
    // The root's `[rust.patch]` rides along: [patch] is honoured only in the
    // workspace root, so this is the one manifest it can go in.
    write_patch_sections(&mut root_cargo, &horus_source, root_manifest.rust.as_ref());

    // ── Write root Cargo.toml ─────────────────────────────────────────────
    let root_path = horus_dir.join("Cargo.toml");
    write_generated(
        project_dir,
        "Cargo.toml",
        &root_path,
        &root_cargo,
        &mut fingerprints,
        &sections_horus_toml_keeps(root_manifest),
    )?;
    let _ = fingerprints.save(project_dir);

    // Not part of the manifest — see write_cargo_config. Taken from the root
    // manifest: cargo config is per build directory, and a workspace is one
    // build directory.
    write_cargo_config(project_dir, &horus_dir, root_manifest.rust.as_ref())?;
    ignore_generated_dir(&horus_dir, BUILD_DIR_IS_GENERATED);

    Ok((root_path, root_cargo))
}

/// Generate a member's Cargo.toml content.
fn generate_member_cargo(
    member_name: &str,
    member_manifest: &HorusManifest,
    member_source_dir: &Path,
    member_horus_dir: &Path,
    root_manifest: &HorusManifest,
    all_members: &[(PathBuf, HorusManifest)],
    horus_dir: &Path,
) -> Result<String> {
    let mut cargo = String::with_capacity(1024);

    writeln!(
        cargo,
        "# Generated by horus from horus.toml — do not edit manually.\n\
         # Edits are lost on the next build; add a [rust] section to horus.toml instead."
    )
    .unwrap();

    // ── [package] ─────────────────────────────────────────────────────────
    writeln!(cargo, "[package]").unwrap();
    writeln!(cargo, "name = \"{}\"", member_name).unwrap();
    writeln!(cargo, "version = \"{}\"", member_manifest.package.version).unwrap();
    writeln!(
        cargo,
        "edition = \"{}\"",
        member_edition(member_manifest, root_manifest)
    )
    .unwrap();
    writeln!(cargo).unwrap();

    // ── Target sections ───────────────────────────────────────────────────
    let target = &member_manifest.package.target_type;

    if matches!(target, TargetType::Lib | TargetType::Both) {
        let lib_path = member_source_dir.join("src/lib.rs");
        if lib_path.exists() {
            let rel = relative_to_horus(&lib_path, member_horus_dir);
            writeln!(cargo, "[lib]").unwrap();
            writeln!(cargo, "path = \"{}\"", rel).unwrap();
            writeln!(cargo).unwrap();
        }
    }

    if matches!(target, TargetType::Bin | TargetType::Both) {
        let main_path = member_source_dir.join("src/main.rs");
        let root_main = member_source_dir.join("main.rs");
        if main_path.exists() {
            let rel = relative_to_horus(&main_path, member_horus_dir);
            write_bin_entry(&mut cargo, &member_manifest.package.name, &rel);
        } else if root_main.exists() {
            let rel = relative_to_horus(&root_main, member_horus_dir);
            write_bin_entry(&mut cargo, &member_manifest.package.name, &rel);
        }
    }

    // ── [dependencies] ────────────────────────────────────────────────────
    writeln!(cargo, "[dependencies]").unwrap();

    // Horus core deps as workspace = true
    for dep_name in &["horus", "horus_core", "horus_macros"] {
        writeln!(cargo, "{}.workspace = true", dep_name).unwrap();
    }
    // serde is implicit (see write_implicit_deps): the message! macro and the
    // documented derive pattern both need serde as a direct dep. Provided at the
    // workspace level; members opt in here. Skip if the member declared it.
    if !member_manifest.dependencies.contains_key("serde") {
        writeln!(cargo, "serde = {{ workspace = true }}").unwrap();
    }

    for (name, dep) in &member_manifest.dependencies {
        // Skip non-Cargo deps (PyPI / system libraries) — they aren't crates and would
        // otherwise leak into the member's Cargo.toml as bogus crates.io deps. The
        // single-package path (write_deps_section) already skips these; the member path
        // had diverged and did not.
        if matches!(dep.effective_source(), DepSource::PyPI | DepSource::System) {
            continue;
        }

        // workspace = true deps
        if let DependencyValue::Detailed(d) = dep {
            if d.workspace {
                if d.features.is_empty() {
                    writeln!(cargo, "{}.workspace = true", name).unwrap();
                } else {
                    writeln!(
                        cargo,
                        "{} = {{ workspace = true, features = [{}] }}",
                        name,
                        d.features
                            .iter()
                            .map(|f| format!("\"{}\"", f))
                            .collect::<Vec<_>>()
                            .join(", ")
                    )
                    .unwrap();
                }
                continue;
            }
        }

        // Inter-member path deps — rewrite to .horus/ sibling
        if let DependencyValue::Detailed(d) = dep {
            if let Some(ref original_path) = d.path {
                if let Some(rewritten) = rewrite_member_path_dep(
                    original_path,
                    member_source_dir,
                    all_members,
                    horus_dir,
                    member_horus_dir,
                ) {
                    writeln!(cargo, "{} = {{ path = \"{}\" }}", name, rewritten).unwrap();
                    continue;
                }
                // Non-member path dep — relativize from member_horus_dir
                let abs_path = member_source_dir.join(original_path);
                let rel = relative_to_horus(&abs_path, member_horus_dir);
                writeln!(cargo, "{} = {{ path = \"{}\" }}", name, rel).unwrap();
                continue;
            }
        }

        // Regular deps (crates.io, git, etc.) — write as-is
        write_single_dep(&mut cargo, name, dep);
    }

    writeln!(cargo).unwrap();

    // ── [rust] passthrough ───────────────────────────────────────────────
    // The package-level half of the section. Before this, a workspace member
    // forwarded nothing at all: `[features]`, `[lints]`, `[target]` and
    // `[build-dependencies]` in a member's horus.toml parsed, passed
    // `horus check` and were dropped on the floor.
    if let Some(rust) = member_rust_section(member_manifest, root_manifest) {
        write_rust_passthrough(&mut cargo, &rust, MEMBER_RUST_SECTIONS);
    }

    Ok(cargo)
}

/// The `[rust]` section to splice into one workspace member's manifest.
///
/// The member's own, plus the root's `[rust.lints]`. Lints are the one table a
/// workspace root can hold on behalf of every member — cargo spells that
/// `[workspace.lints]` in the root and `lints.workspace = true` in each member,
/// and writing the groups straight into the members is the same thing with one
/// fewer indirection and no way for the two halves to get out of step.
///
/// A group the member also declares is the member's: `[rust.lints.clippy]` in a
/// member replaces the root's `clippy` table rather than merging into it, which
/// is what cargo's own `lints.workspace` opt-out does at the same granularity.
///
/// `None` when there is nothing to write, so a member with no `[rust]` section
/// and a root with no lints produces exactly the manifest it did before.
fn member_rust_section(
    member: &HorusManifest,
    root: &HorusManifest,
) -> Option<crate::manifest::RustConfig> {
    let mut rust = member.rust.clone().unwrap_or_default();

    let root_lints = root.rust.as_ref().and_then(|r| r.lints.clone());
    rust.lints = match (root_lints, rust.lints) {
        (Some(mut inherited), Some(own)) => {
            for (group, table) in own {
                inherited.insert(group, table);
            }
            Some(inherited)
        }
        (inherited, own) => own.or(inherited),
    };

    let mut carried = rust.clone();
    carried.edition = None;
    carried.rustflags.clear();
    carried.patch = None;
    carried.profile = None;
    if carried.is_empty() {
        return None;
    }
    Some(rust)
}

/// Write a single dependency in Cargo.toml format.
fn write_single_dep(cargo: &mut String, name: &str, dep: &DependencyValue) {
    match dep {
        DependencyValue::Simple(v) => {
            writeln!(cargo, "{} = \"{}\"", name, v).unwrap();
        }
        DependencyValue::Detailed(d) => {
            if d.git.is_none() && d.features.is_empty() && !d.optional {
                // Bare version requirement, no source override or modifiers → short form.
                let version = d.version.as_deref().unwrap_or("*");
                writeln!(cargo, "{} = \"{}\"", name, version).unwrap();
            } else {
                // Inline table. The source token comes first — a git source takes
                // precedence over a version requirement — then features and the
                // optional flag are appended regardless of source. Previously the git
                // branch and the features/optional branches were mutually exclusive,
                // so a member `{ git = "...", features = [...] }` dep silently dropped
                // its git source (emitting a bogus `version = "*"` crates.io dep) and a
                // git+optional dep dropped `optional = true`.
                let mut parts: Vec<String> = Vec::new();
                if let Some(ref git) = d.git {
                    parts.push(format!("git = \"{}\"", git));
                    if let Some(ref branch) = d.branch {
                        parts.push(format!("branch = \"{}\"", branch));
                    }
                    if let Some(ref tag) = d.tag {
                        parts.push(format!("tag = \"{}\"", tag));
                    }
                    if let Some(ref rev) = d.rev {
                        parts.push(format!("rev = \"{}\"", rev));
                    }
                } else {
                    parts.push(format!(
                        "version = \"{}\"",
                        d.version.as_deref().unwrap_or("*")
                    ));
                }
                if !d.features.is_empty() {
                    let feats = d
                        .features
                        .iter()
                        .map(|f| format!("\"{}\"", f))
                        .collect::<Vec<_>>()
                        .join(", ");
                    parts.push(format!("features = [{}]", feats));
                }
                if d.optional {
                    parts.push("optional = true".to_string());
                }
                writeln!(cargo, "{} = {{ {} }}", name, parts.join(", ")).unwrap();
            }
        }
    }
}

/// Detect inter-member path deps and rewrite to `.horus/` sibling directories.
fn rewrite_member_path_dep(
    original_path: &str,
    member_source_dir: &Path,
    all_members: &[(PathBuf, HorusManifest)],
    horus_dir: &Path,
    member_horus_dir: &Path,
) -> Option<String> {
    let target_dir = member_source_dir.join(original_path);
    let target_canonical = target_dir.canonicalize().ok()?;

    let project_dir = horus_dir.parent()?;

    for (rel_path, member_manifest) in all_members {
        let member_dir = project_dir.join(rel_path);
        if let Ok(member_canonical) = member_dir.canonicalize() {
            if member_canonical == target_canonical {
                let target_name = sanitize_cargo_name(&member_manifest.package.name);
                let target_horus = horus_dir.join(&target_name);
                return Some(relative_to_horus(&target_horus, member_horus_dir));
            }
        }
    }

    None
}

